/** Porta la griglia nativa del set (`0 0 24 24`) sul viewBox fisso che
 *  addIcon() impone. Senza questo wrapper i glifi finirebbero fuori scala e,
 *  con un'origine negativa come quella di Material, del tutto fuori dal box. */
const TRANSFORM = 'scale(4.1666667)';

/** Avvolge il body del glifo in ciò che addIcon() si aspetta: trasformato sul
 *  suo viewBox fisso, e a currentColor.
 *
 *  `data-mv-icon` è il marker con cui il CSS riconosce i nostri glifi. Serve
 *  un attributo dedicato e non il transform: quel valore cambia con il set
 *  (Phosphor scalava e basta, Material scala e trasla), e un selettore che lo
 *  cita smetterebbe silenziosamente di applicarsi al primo cambio famiglia.
 *
 *  Il body viene interpolato intero, mai spezzato: contiene i path del glifo
 *  con le loro opacità, e i path data sono pieni di virgole e spazi — un
 *  qualsiasi split li frammenterebbe in glifi corrotti. */
function body(inner: string): string {
  return `<g data-mv-icon transform="${TRANSFORM}" fill="currentColor">${inner}</g>`;
}

/** Quanti nomi Lucide questo modulo sovrascrive. */
export const MV_ICON_COUNT = 425;

/** Nomi Lucide coperti dall'override, per test e diagnostica. */
export const MV_ICON_NAMES: readonly string[] = Object.keys(PATHS);

/** `true` se il nome è coperto. Serve dove il nome arriva da config utente
 *  (le folder icon di Portal) e va validato prima dell'uso. */
export function mvHasIcon(name: string): boolean {
  return name in PATHS;
}

/** Le varianti alternative, per le icone che si vedono davvero.
 *
 *  Non tutte: sei varianti di ogni nome peserebbero ~1,7 MB. Qui ci sono le
 *  ~150 che compaiono nel chrome, nella sidebar e nella suite; le altre
 *  restano alla variante di base, e in pratica nessuno le vede cambiare
 *  perché appaiono solo in menu e finestre di rado.
 *
 *  Ogni variante è un JSON `nome → body` compresso (deflate raw, base64),
 *  con le sole righe che differiscono dalla base. A runtime ne serve una sola,
 *  quindi si paga la decompressione di quella e basta. */
const VARIANT_PACKED: Record<string, string> = {
  'bold': '',
  'broken': '',
  'line-duotone': '',
  'linear': '',
  'outline': '',
};

const unpacked: Record<string, Record<string, string>> = {};

/** La tabella della variante scelta, decompressa alla prima richiesta.
 *  Sincrona di proposito: `installMvIcons` deve registrare i glifi prima che
 *  qualunque view renderizzi, senza un await in mezzo. */
function variantPaths(variant?: string): Record<string, string> {
  const packed = variant ? VARIANT_PACKED[variant] : undefined;
  if (!variant || !packed) return {};
  return (unpacked[variant] ??= JSON.parse(
    strFromU8(inflateSync(Uint8Array.from(atob(packed), (c) => c.charCodeAt(0)))),
  ) as Record<string, string>);
}

/** Le varianti selezionabili, nell'ordine in cui ha senso mostrarle. */
